def move_one_ball(arr):
    if not arr:
        return True

    def count_drops(idx):
        if idx == len(arr) - 1:
            # Check the wrap-around condition
            return 1 if arr[-1] > arr[0] else 0

        current_drop = 1 if arr[idx] > arr[idx + 1] else 0
        return current_drop + count_drops(idx + 1)

    # A sorted array that is cyclically shifted will have at most one 
    # point where arr[i] > arr[i+1].
    # If the array is already sorted, count_drops will return 0.
    # If it is shifted, it will return 1.
    return count_drops(0) <= 1

