import math

def closest_integer(value):
    """
    Rounds a number to the nearest integer, rounding 0.5 cases away from zero.
    """
    num = float(value)

    # Handle the equidistant case (x.5) explicitly
    abs_num = abs(num)
    if abs_num % 1 == 0.5:
