def do_algebra(operators, operands):
    """
    Evaluates a mathematical expression constructed from a list of 
    operands and operators, respecting standard operator precedence.
    """
    if not operands:
        return 0

    # Build the expression string by interleaving operands and operators
    # Example: operands=[2, 3, 4], operators=['+', '*'] -> "2 + 3 * 4"
    expression_parts = [str(operands[0])]
    for op, num in zip(operators, operands[1:]):
        expression_parts.append(f"{op} {num}")

    return eval(" ".join(expression_parts))

