def search(lst):
    def get_freq(val, l):
        if not l:
            return 0
        return (1 if l[0] == val else 0) + get_freq(val, l[1:])

    def find_max(unique_elements, current_max):
        if not unique_elements:
            return current_max

        val = unique_elements[0]
        if get_freq(val, lst) >= val:
            new_max = val if val > current_max else current_max
            return find_max(unique_elements[1:], new_max)
        else:
            return find_max(unique_elements[1:], current_max)

    def get_unique(l, seen):
        if not l:
            return []
        if l[0] not in seen:
            return [l[0]] + get_unique(l[1:], seen | {l[0]})
        return get_unique(l[1:], seen)

    result = find_max(get_unique(lst, set()), -1)
